import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"第二卦 坤 坤为地 坤上坤下","description":"周易 - 第二卦 坤 坤为地 坤上坤下","frontmatter":{"title":"第二卦 坤 坤为地 坤上坤下","description":"周易 - 第二卦 坤 坤为地 坤上坤下"},"headers":[],"relativePath":"zh/classics/zhouyi/003.md","filePath":"zh/classics/zhouyi/003.md"}'),l={name:"zh/classics/zhouyi/003.md"};function t(n,a,s,d,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="坤" tabindex="-1">坤 <a class="header-anchor" href="#坤" aria-label="Permalink to “坤”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>元，亨，利牝马之贞。君子有攸往，先迷后得主，利西南得朋，东北丧朋。安贞吉。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>至哉坤元，万物资生，乃顺承天。坤厚载物，德合无疆。含弘光大，品物咸亨。牝马地类，行地无疆，柔顺利贞。君子攸行，先迷失道，后顺得常。西南得朋，乃与类行；东北丧朋，乃终有庆。安贞之吉，应地无疆。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>地势坤，君子以厚德载物。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>履霜，坚冰至。象曰：履霜坚冰，阴始凝也。驯致其道，至坚冰也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>直，方，大，不习无不利。象曰：六二之动，直以方也。不习无不利，地道光也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>含章可贞。或从王事，无成有终。象曰：含章可贞；以时发也。或从王事，知光大也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>括囊；无咎，无誉。象曰：括囊无咎，慎不害也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>黄裳，元吉。象曰：黄裳元吉，文在中也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>战龙於野，其血玄黄。象曰：战龙於野，其道穷也。</p><h3 id="用六" tabindex="-1">用六 <a class="header-anchor" href="#用六" aria-label="Permalink to “用六”">​</a></h3><p>利永贞。象曰：用六永贞，以大终也。</p><h2 id="文言" tabindex="-1">文言 <a class="header-anchor" href="#文言" aria-label="Permalink to “文言”">​</a></h2><p>坤至柔，而动也刚，至静而德方，后得主而有常，含万物而化光。坤其道顺乎？承天而时行。积善之家，必有馀庆；积不善之家，必有馀殃。臣弑其君，子弑其父，非一朝一夕之故，其所由来者渐矣，由辩之不早辩也。易曰：「履霜坚冰至。」盖言顺也。直其正也，方其义也。君子敬以直内，义以方外，敬义立，而德不孤。「直，方，大，不习无不利」；则不疑其所行也。阴虽有美，含之；以从王事，弗敢成也。地道也，妻道也，臣道也。地道无成，而代有终也。天地变化，草木蕃；天地闭，贤人隐。易曰：「括囊；无咎，无誉。」盖言谨也。君子黄中通理，正位居体，美在其中，而畅於四支，发於事业，美之至也。阴疑於阳，必战。为其嫌於无阳也，故称龙焉。犹未离其类也，故称血焉。夫玄黄者，天地之杂也，天玄而地黄。</p>',23)])])}const _=e(l,[["render",t]]);export{b as __pageData,_ as default};
